mapper.select:
SELECT AREA_CODE, MATERIAL_CODE, CONCAT('areaCode', AREA_CODE) as AREA_CODE_SHOW,
SUM(SALE_QTY) as SALE_QTY
from T_MDM_HISTORY_SALE_RECORD
where IS_DELETE = 0
AND `YEAR_MONTH` >= #{minYearMonth}
AND `YEAR_MONTH` <= #{maxYearMonth}

    AND MATERIAL_CODE IN

        #{item}


group by AREA_CODE, MATERIAL_CODE

SELECT `YEAR`, `MONTH`, MATERIAL_CODE, CONCAT('month', `MONTH`) as AREA_CODE_SHOW,
SUM(SALE_QTY) as SALE_QTY
from T_MDM_HISTORY_SALE_RECORD
where IS_DELETE = 0
AND `YEAR_MONTH` >= #{minYearMonth}
AND `YEAR_MONTH` <= #{maxYearMonth}

    AND MATERIAL_CODE IN

        #{item}


group by `YEAR`, `MONTH`, MATERIAL_CODE
ORDER BY `YEAR`, `MONTH`
